package net.civeira.phylax.feature.access.userinvitation.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userinvitation.domain.UserInvitation;
import net.civeira.phylax.feature.access.userinvitation.domain.valueobject.MetadataJsonVO;

class MetadataJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of metadata json of user invitation")
  void test_metadata_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    MetadataJsonValueHolder<Object> value = new MetadataJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.metadataJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getMetadataJsonValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getMetadataJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.metadataJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMetadataJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getMetadataJson().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of metadata json of user invitation")
  void test_metadata_json_value_holder_assign_value_object() {
    Object holder = new Object();
    MetadataJsonValueHolder<Object> value = new MetadataJsonValueHolder<>(holder);
    MetadataJsonVO vo = MetadataJsonVO.from("one");
    Assertions.assertFalse(value.getMetadataJsonValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.metadataJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMetadataJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.metadataJson(Optional.empty()));
    Assertions.assertFalse(value.getMetadataJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.metadataJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMetadataJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of metadata json of user invitation against the original")
  void test_metadata_json_value_holder_read() {
    Object holder = new Object();
    MetadataJsonValueHolder<Object> value = new MetadataJsonValueHolder<>(holder);
    MetadataJsonVO vo = MetadataJsonVO.from("one");
    MetadataJsonVO other = MetadataJsonVO.from("one");
    UserInvitation original = Mockito.mock(UserInvitation.class);
    Mockito.when(original.getMetadataJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMetadataJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMetadataJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.metadataJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMetadataJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMetadataJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of metadata json of user invitation")
  void test_metadata_json_value_holder_unset() {
    Object holder = new Object();
    MetadataJsonValueHolder<Object> value = new MetadataJsonValueHolder<>(holder);
    MetadataJsonVO vo = MetadataJsonVO.from("one");
    value.metadataJson(vo);
    Assertions.assertSame(holder, value.unsetMetadataJsonIfMatches("metadataJson_other"));
    Assertions.assertTrue(value.getMetadataJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMetadataJsonIfMatches("metadataJson"));
    Assertions.assertFalse(value.getMetadataJsonValue().isPresent(),
        "The field name must clear the value");
    value.metadataJson(vo);
    Assertions.assertSame(holder, value.unsetMetadataJson());
    Assertions.assertFalse(value.getMetadataJsonValue().isPresent(), "Unset must clear the value");
  }
}
